DO $$ DECLARE test_customer uuid; test_quantity integer; BEGIN SELECT o.customer_id INTO test_customer FROM public.orders o JOIN public.customers c ON c.id = o.customer_id WHERE o.id = '102c61db-4c05-4287-af4e-cd0f2d616a72' AND c.full_name = 'Security Checkout Test' AND o.delivery_address_note = 'Security test — do not fulfil'; IF test_customer IS NOT NULL THEN SELECT sum(quantity) INTO test_quantity FROM public.order_items WHERE order_id = '102c61db-4c05-4287-af4e-cd0f2d616a72' AND variant_id = '89f65618-a014-43be-a573-6034dee3d785'; UPDATE public.product_variants SET stock_quantity = stock_quantity + coalesce(test_quantity, 0) WHERE id = '89f65618-a014-43be-a573-6034dee3d785'; DELETE FROM public.order_items WHERE order_id = '102c61db-4c05-4287-af4e-cd0f2d616a72'; DELETE FROM public.orders WHERE id = '102c61db-4c05-4287-af4e-cd0f2d616a72'; DELETE FROM public.customers WHERE id = test_customer AND full_name = 'Security Checkout Test' AND NOT EXISTS (SELECT 1 FROM public.orders WHERE customer_id = test_customer); END IF; END $$;